package com.scorecraft;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.web.client.TestRestTemplate; import org.springframework.boot.test.web.server.LocalServerPort; import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class MatchControllerTest { @LocalServerPort int port; @Autowired TestRestTemplate http; @Test void exposesLiveMatches(){var body=http.getForObject("http://localhost:"+port+"/api/matches",String.class);assertThat(body).contains("India v Australia","Wankhede Stadium");} }
